69	    /// Create an Aarch64 MacroAssembler.
70	    pub fn new(
71	        ptr_size: impl PtrSize,
72	        shared_flags: settings::Flags,
73	        isa_flags: aarch64::settings::Flags,
74	    ) -> Result<Self> {
75	        Ok(Self {
76	            sp_max: 0,
77	            stack_max_use_add: None,
78	            asm: Assembler::new(shared_flags.clone(), isa_flags),
79	            sp_offset: 0u32,
80	            ptr_size: ptr_type_from_ptr_size(ptr_size.size()).try_into()?,
81	            scratch_scope: RegAlloc::from(scratch_gpr_bitset(), scratch_fpr_bitset()),
82	            shared_flags,
83	        })
84	    }
